class TopKMaintainer {
  constructor(k) {
    this.k = k;
    this.counts = new Map();
    this.heap = new MinHeap((a,b)=>a[0]-b[0]); // stores [count, key]
    this.inTop = new Set();
  }
  // update and getTopK methods would implement the described approach
